=== FILE: irq_ctrl_cov_tb.sv ===
// Coverage testbench for irq_ctrl.v (N = 8). Extends irq_ctrl_idle_tb.sv:
// drives every source in level and edge mode, walks the fixed priority,
// acknowledges every source through CLAIM, exercises W1C, out-of-range
// acknowledges, detection-over-clear at the same edge, mixed modes and a
// mid-run reset. Inputs change on the falling clock edge; reads are checked
// 1 ns after a falling edge, well before the next rising edge.
`timescale 1ns / 1ps
module irq_ctrl_cov_tb;
    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic [7:0]  src = 8'h00;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;
    logic [31:0] rdata;
    logic        irq;
    logic [4:0]  irq_id;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;
    logic [7:0]  m;

    localparam logic [1:0] A_ENABLE = 2'd0, A_MODE = 2'd1, A_PENDING = 2'd2, A_CLAIM = 2'd3;

    irq_ctrl #(.N(8)) dut (.clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr), .wdata(wdata),
                           .rdata(rdata), .irq(irq), .irq_id(irq_id));
    always #20 clk = ~clk;

    task automatic check_reg(input logic [1:0] a, input logic [31:0] expected);
        addr = a;
        #1;
        checks++;
        if (rdata !== expected) begin
            errors++;
            $display("MISMATCH t=%0t addr=%0d rdata=%h expected=%h", $time, a, rdata, expected);
        end
    endtask

    task automatic check_irq(input logic exp_irq, input logic [4:0] exp_id);
        #1;
        checks++;
        if (irq !== exp_irq || irq_id !== exp_id) begin
            errors++;
            $display("MISMATCH t=%0t irq=%b irq_id=%0d expected irq=%b irq_id=%0d", $time, irq, irq_id, exp_irq, exp_id);
        end
    endtask

    task automatic wr(input logic [1:0] a, input logic [31:0] d);
        @(negedge clk);
        we = 1'b1; addr = a; wdata = d;
        @(negedge clk);
        we = 1'b0; wdata = 32'd0;
    endtask

    task automatic set_src(input logic [7:0] s);
        @(negedge clk);
        src = s;
        @(negedge clk);
    endtask

    task automatic cycles(input int n);
        repeat (n) @(negedge clk);
    endtask

    initial begin
        // 1. Reset values.
        repeat (3) @(posedge clk);
        @(negedge clk);
        rst_n = 1'b1;
        check_reg(A_ENABLE, 32'd0);
        check_reg(A_MODE, 32'd0);
        check_reg(A_PENDING, 32'd0);
        check_reg(A_CLAIM, 32'd0);
        check_irq(1'b0, 5'd0);

        // 2. Register writes; bits 8 and up are ignored.
        wr(A_ENABLE, 32'hFFFF_FFFF); check_reg(A_ENABLE, 32'h0000_00FF);
        wr(A_MODE, 32'hFFFF_FFFF);   check_reg(A_MODE, 32'h0000_00FF);
        check_irq(1'b0, 5'd0);
        wr(A_ENABLE, 32'hFFFF_FF5A); check_reg(A_ENABLE, 32'h0000_005A);
        wr(A_MODE, 32'h0000_00A5);   check_reg(A_MODE, 32'h0000_00A5);
        wr(A_ENABLE, 32'h0000_0000); check_reg(A_ENABLE, 32'd0);
        wr(A_MODE, 32'h0000_0000);   check_reg(A_MODE, 32'd0);
        wr(A_PENDING, 32'hFFFF_FFFF); check_reg(A_PENDING, 32'd0);

        // 3. Level mode, one source: enable masking, detection beats clear.
        set_src(8'h08);
        check_reg(A_PENDING, 32'h0000_0008);
        check_irq(1'b0, 5'd0);
        check_reg(A_CLAIM, 32'd0);
        wr(A_ENABLE, 32'h0000_00FF);
        check_irq(1'b1, 5'd3);
        check_reg(A_CLAIM, 32'h8000_0003);
        wr(A_PENDING, 32'h0000_0008); check_reg(A_PENDING, 32'h0000_0008);
        wr(A_CLAIM, 32'd3);           check_reg(A_PENDING, 32'h0000_0008);
        set_src(8'h00);               check_reg(A_PENDING, 32'h0000_0008);
        wr(A_PENDING, 32'h0000_0008);
        check_reg(A_PENDING, 32'd0);
        check_irq(1'b0, 5'd0);

        // 4. Level mode, all sources: fixed priority walked by enable masking.
        set_src(8'hFF);
        check_reg(A_PENDING, 32'h0000_00FF);
        check_irq(1'b1, 5'd0);
        check_reg(A_CLAIM, 32'h8000_0000);
        for (int k = 1; k < 8; k++) begin
            m = 8'hFF << k;
            wr(A_ENABLE, {24'd0, m});
            check_irq(1'b1, 5'(k));
            check_reg(A_CLAIM, 32'h8000_0000 | 32'(k));
        end
        wr(A_ENABLE, 32'h0000_0000);
        check_irq(1'b0, 5'd0);
        check_reg(A_CLAIM, 32'd0);
        wr(A_ENABLE, 32'h0000_00FF);
        set_src(8'h00);
        check_reg(A_PENDING, 32'h0000_00FF);
        wr(A_PENDING, 32'h0000_00FF);
        check_reg(A_PENDING, 32'd0);
        check_irq(1'b0, 5'd0);

        // 5. Edge mode: all sources rise together, acknowledge each in turn.
        wr(A_MODE, 32'h0000_00FF);
        check_reg(A_MODE, 32'h0000_00FF);
        set_src(8'hFF);
        check_reg(A_PENDING, 32'h0000_00FF);
        for (int k = 0; k < 8; k++) begin
            check_irq(1'b1, 5'(k));
            check_reg(A_CLAIM, 32'h8000_0000 | 32'(k));
            wr(A_CLAIM, 32'(k));
            m = 8'hFF << (k + 1);
            check_reg(A_PENDING, {24'd0, m});
        end
        check_irq(1'b0, 5'd0);
        check_reg(A_CLAIM, 32'd0);
        cycles(2);
        check_reg(A_PENDING, 32'd0);

        // 6. Edge mode: falling edges, out-of-range acknowledge, upper wdata bits,
        //    and detection beating a clear at the same edge.
        set_src(8'h00);
        check_reg(A_PENDING, 32'd0);
        check_irq(1'b0, 5'd0);
        set_src(8'h24);
        check_reg(A_PENDING, 32'h0000_0024);
        check_irq(1'b1, 5'd2);
        wr(A_CLAIM, 32'd8);           check_reg(A_PENDING, 32'h0000_0024);
        wr(A_CLAIM, 32'h0000_001F);   check_reg(A_PENDING, 32'h0000_0024);
        wr(A_CLAIM, 32'hFFFF_FFE5);
        check_reg(A_PENDING, 32'h0000_0004);
        check_irq(1'b1, 5'd2);
        wr(A_PENDING, 32'hFFFF_FF04);
        check_reg(A_PENDING, 32'd0);
        check_irq(1'b0, 5'd0);

        set_src(8'h00);
        set_src(8'h04);
        set_src(8'h00);
        check_reg(A_PENDING, 32'h0000_0004);
        @(negedge clk);
        src = 8'h04; we = 1'b1; addr = A_PENDING; wdata = 32'h0000_0004;
        @(negedge clk);
        we = 1'b0; wdata = 32'd0;
        check_reg(A_PENDING, 32'h0000_0004);
        wr(A_PENDING, 32'h0000_0004);
        check_reg(A_PENDING, 32'd0);

        set_src(8'h00);
        set_src(8'h04);
        set_src(8'h00);
        check_reg(A_PENDING, 32'h0000_0004);
        @(negedge clk);
        src = 8'h04; we = 1'b1; addr = A_CLAIM; wdata = 32'd2;
        @(negedge clk);
        we = 1'b0; wdata = 32'd0;
        check_reg(A_PENDING, 32'h0000_0004);
        wr(A_CLAIM, 32'd2);
        check_reg(A_PENDING, 32'd0);
        check_irq(1'b0, 5'd0);

        // 7. Mixed modes: sources 0-3 edge, 4-7 level.
        set_src(8'h00);
        wr(A_PENDING, 32'h0000_00FF);
        check_reg(A_PENDING, 32'd0);
        wr(A_MODE, 32'h0000_000F);
        check_reg(A_MODE, 32'h0000_000F);
        set_src(8'hFF);
        check_reg(A_PENDING, 32'h0000_00FF);
        wr(A_PENDING, 32'h0000_00FF);
        check_reg(A_PENDING, 32'h0000_00F0);
        check_irq(1'b1, 5'd4);
        check_reg(A_CLAIM, 32'h8000_0004);

        // 8. Reset again with nonzero state.
        @(negedge clk);
        src = 8'h00;
        rst_n = 1'b0;
        cycles(2);
        rst_n = 1'b1;
        check_reg(A_ENABLE, 32'd0);
        check_reg(A_MODE, 32'd0);
        check_reg(A_PENDING, 32'd0);
        check_reg(A_CLAIM, 32'd0);
        check_irq(1'b0, 5'd0);

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
